 if(Math.cos(yaw)>-.2){let eyeX=headX+Math.sign(Math.sin(yaw)||1)*bodyW*.16;circle(eyeX,headY+head*.08,Math.max(1,sc*.018),'#f4bd81')}
 // exposed nape glows only while titan faces away
 let toPlayer=Math.atan2(game.player.x-t.x,game.player.z-t.z),delta=Math.abs(Math.atan2(Math.sin(toPlayer-yaw),Math.cos(toPlayer-yaw)));let isBehind=delta>2.05; if(isBehind){let ny=neckY;ctx.fillStyle='#dc7357';ctx.shadowColor='#ef7650';ctx.shadowBlur=sc*.18;ctx.fillRect(base.x-bodyW*.19,ny-head*.09,bodyW*.38,Math.max(2,head*.12));ctx.shadowBlur=0}
